import java.util.HashMap;
import java.util.Map;

class Solution {
    public int tallestBillboard(int[] rods) {
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(0, 0);

        for (int rod : rods) {
            Map<Integer, Integer> snapshot = new HashMap<>(dp);
            for (Map.Entry<Integer, Integer> entry : snapshot.entrySet()) {
                int diff = entry.getKey();
                int taller = entry.getValue();

                dp.merge(diff + rod, taller + rod, Math::max);

                int newDiff = Math.abs(diff - rod);
                int newTaller = taller + Math.max(0, rod - diff);
                dp.merge(newDiff, newTaller, Math::max);
            }
        }

        return dp.getOrDefault(0, 0);
    }
}

import java.util.Arrays;

class Solution {
    public int tallestBillboard(int[] rods) {
        int sum = 0;
        for (int rod : rods) {
            sum += rod;
        }

        int[] dp = new int[sum + 1];
        Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int rod : rods) {
            int[] previous = dp.clone();
            for (int diff = 0; diff <= sum - rod; diff++) {
                if (previous[diff] < 0) {
                    continue;
                }

                dp[diff + rod] = Math.max(dp[diff + rod], previous[diff]);

                int newDiff = Math.abs(diff - rod);
                int newShorter = previous[diff] + Math.min(diff, rod);
                dp[newDiff] = Math.max(dp[newDiff], newShorter);
            }
        }

        return dp[0];
    }
}

import java.util.Arrays;

class Solution {
    public int tallestBillboard(int[] rods) {
        int sum = 0;
        for (int rod : rods) {
            sum += rod;
        }

        int offset = sum;
        int negative = -1_000_000;
        int[] dp = new int[2 * sum + 1];
        Arrays.fill(dp, negative);
        dp[offset] = 0;

        for (int rod : rods) {
            int[] next = dp.clone();
            for (int diff = -sum; diff <= sum; diff++) {
                int leftHeight = dp[offset + diff];
                if (leftHeight < 0) {
                    continue;
                }
                if (diff + rod <= sum) {
                    next[offset + diff + rod] = Math.max(next[offset + diff + rod], leftHeight + rod);
                }
                if (diff - rod >= -sum) {
                    next[offset + diff - rod] = Math.max(next[offset + diff - rod], leftHeight);
                }
            }
            dp = next;
        }

        return dp[offset];
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    private int[] rods;
    private Map<Long, Integer> memo = new HashMap<>();
    private static final int NEGATIVE = -1_000_000;

    public int tallestBillboard(int[] rods) {
        this.rods = rods;
        return Math.max(0, dfs(0, 0));
    }

    private int dfs(int index, int diff) {
        if (index == rods.length) {
            return diff == 0 ? 0 : NEGATIVE;
        }
        long key = (((long) index) << 32) ^ (diff + 5000L);
        Integer cached = memo.get(key);
        if (cached != null) {
            return cached;
        }

        int rod = rods[index];
        int skip = dfs(index + 1, diff);
        int useLeft = rod + dfs(index + 1, diff + rod);
        int useRight = dfs(index + 1, diff - rod);
        int best = Math.max(skip, Math.max(useLeft, useRight));
        memo.put(key, best);
        return best;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public int tallestBillboard(int[] rods) {
        int half = rods.length / 2;
        Map<Integer, Integer> left = enumerate(rods, 0, half);
        Map<Integer, Integer> right = enumerate(rods, half, rods.length);

        int answer = 0;
        for (Map.Entry<Integer, Integer> entry : left.entrySet()) {
            int diff = entry.getKey();
            Integer rightLeftHeight = right.get(-diff);
            if (rightLeftHeight != null) {
                answer = Math.max(answer, entry.getValue() + rightLeftHeight);
            }
        }
        return answer;
    }

    private Map<Integer, Integer> enumerate(int[] rods, int start, int end) {
        Map<Integer, Integer> states = new HashMap<>();
        states.put(0, 0);
        for (int i = start; i < end; i++) {
            int rod = rods[i];
            Map<Integer, Integer> next = new HashMap<>(states);
            for (Map.Entry<Integer, Integer> entry : states.entrySet()) {
                int diff = entry.getKey();
                int leftHeight = entry.getValue();
                next.merge(diff + rod, leftHeight + rod, Math::max);
                next.merge(diff - rod, leftHeight, Math::max);
            }
            states = next;
        }
        return states;
    }
}
